for (const [code, d] of Object.entries(FILL)) for (const [k, v] of Object.entries(d)) if (!(k in D[code])) D[code][k] = v;

export function detectLang() {
  for (const raw of navigator.languages || [navigator.language || 'en']) {
    const l = raw.toLowerCase();
    if (l.startsWith('zh')) return /tw|hk|mo|hant/.test(l) ? 'zh-TW' : 'zh-CN';
    const hit = LANGS.find(x => x.code.toLowerCase() === l || x.code === l.split('-')[0]);
    if (hit) return hit.code;
  }
  return 'en';
}

export function setLang(code) {
  lang = D[code] ? code : 'en';
  document.documentElement.lang = lang;
}
export const getLang = () => lang;

export function t(key, vars = {}) {
  let v = D[lang][key] ?? D.en[key] ?? key;
  if (typeof v === 'object') {
    const fallback = typeof D.en[key] === 'object' ? D.en[key] : {};
    v = v[new Intl.PluralRules(lang).select(vars.n ?? 0)] ?? v.other ?? fallback.other;
  }
  return v.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? (k === 'chars' ? BAD_CHARS : '')));
}

// Fill elements marked with data-i18n (text), data-i18n-title (+ optional data-kbd), data-i18n-ph (placeholder).
export function applyI18n(root = document) {
  for (const el of root.querySelectorAll('[data-i18n]')) el.textContent = t(el.dataset.i18n);
  for (const el of root.querySelectorAll('[data-i18n-title]')) el.title = t(el.dataset.i18nTitle) + (el.dataset.kbd ? ` (${el.dataset.kbd})` : '');
  for (const el of root.querySelectorAll('[data-i18n-ph]')) el.placeholder = t(el.dataset.i18nPh);
}
